changeSet.sql:
-- Training cleanup wipes all clinical data, delivered or not. The bypass is
-- transaction-local and only granted in a training installation.
CREATE FUNCTION clinlims.delivered_lock_bypassed() RETURNS boolean
LANGUAGE sql STABLE AS $$
 SELECT coalesce(current_setting('openelis.delivered_lock_bypass', true), '') = 'training-cleanup'
$$;

CREATE FUNCTION clinlims.allow_training_cleanup_of_delivered() RETURNS integer
LANGUAGE plpgsql SECURITY INVOKER SET search_path = pg_catalog, clinlims AS $$
BEGIN
 IF NOT EXISTS (SELECT 1 FROM clinlims.site_information
                WHERE name = 'TrainingInstallation' AND lower(trim(value)) = 'true') THEN
  RAISE EXCEPTION 'Delivered results may only be cleared in a training installation';
 END IF;
 PERFORM set_config('openelis.delivered_lock_bypass', 'training-cleanup', true);
 RETURN 1;
END $$;

CREATE FUNCTION clinlims.guard_delivered_analysis() RETURNS trigger
LANGUAGE plpgsql SET search_path = pg_catalog, clinlims AS $$
DECLARE editable text[] := ARRAY['delivered_date', 'delivered_by', 'delivery_correction_reason',
  'lastupdated', 'sys_user_id', 'fhir_uuid', 'printed_date', 'corrected'];
BEGIN
 IF OLD.delivered_date IS NULL OR clinlims.delivered_lock_bypassed() THEN
  RETURN COALESCE(NEW, OLD);
 END IF;
 IF TG_OP = 'UPDATE' AND (to_jsonb(OLD) - editable) IS NOT DISTINCT FROM (to_jsonb(NEW) - editable) THEN
  RETURN NEW;
 END IF;
 RAISE EXCEPTION 'analysis.delivered.locked' USING ERRCODE = 'P0001',
  DETAIL = 'Analysis ' || OLD.id || ' was delivered; create an amendment instead';
END $$;

CREATE FUNCTION clinlims.guard_delivered_analysis_child() RETURNS trigger
LANGUAGE plpgsql SET search_path = pg_catalog, clinlims AS $$
DECLARE technical text[] := ARRAY['lastupdated', 'last_updated', 'sys_user_id', 'fhir_uuid'];
 old_id numeric; new_id numeric;
BEGIN
 IF clinlims.delivered_lock_bypassed() THEN
  RETURN COALESCE(NEW, OLD);
 END IF;
 IF TG_OP = 'UPDATE' AND (to_jsonb(OLD) - technical) IS NOT DISTINCT FROM (to_jsonb(NEW) - technical) THEN
  RETURN NEW;
 END IF;
 IF TG_OP <> 'INSERT' THEN old_id := (to_jsonb(OLD)->>'analysis_id')::numeric; END IF;
 IF TG_OP <> 'DELETE' THEN new_id := (to_jsonb(NEW)->>'analysis_id')::numeric; END IF;
 IF EXISTS (SELECT 1 FROM clinlims.analysis a
            WHERE a.id IN (old_id, new_id) AND a.delivered_date IS NOT NULL) THEN
  RAISE EXCEPTION 'analysis.delivered.locked' USING ERRCODE = 'P0001',
   DETAIL = TG_TABLE_NAME || ' belongs to a delivered analysis; create an amendment instead';
 END IF;
 RETURN COALESCE(NEW, OLD);
END $$;
